CREATE OR REPLACE VIEW `view_decay_fz` AS
with filedate as (select max(`tbl_import_aenderungen`.`filedate`) AS `fd` from `tbl_import_aenderungen`), dataset as (select `a`.`wert` AS `wert`,`a`.`datum` AS `datum`,least(`a`.`bekannt_seit`,`a`.`datum` + interval case when `f`.`Schicht` = 'früh' then 6 when `f`.`Schicht` = 'spät' then 14 else 0 end hour) AS `bekannt_seit`,greatest(weekday(`a`.`bekannt_seit`) + (to_days(`a`.`datum`) - to_days(`a`.`bekannt_seit`)),weekday(`a`.`datum`)) AS `wochentag`,coalesce(`f`.`Schicht`,'') AS `schicht`,to_days(`a`.`datum`) - to_days(`a`.`bekannt_seit`) AS `dd`,weekday(`a`.`bekannt_seit`) AS `wd_b`,weekday(`a`.`datum`) AS `wd_d`,weekday(`a`.`bekannt_seit`) + (to_days(`a`.`datum`) - to_days(`a`.`bekannt_seit`)) AS `wd2` from ((((`tbl_ueb_aend_fz_kalender` `a` left join `tbl_datum` `d` on(`a`.`datum` = `d`.`datum`)) left join `tbl_ueb_personalakte_scd` `p` on(`a`.`persnr` = `p`.`persnr` and `a`.`datum` between `p`.`gueltig_von` and `p`.`gueltig_bis`)) left join `tbl_ueb_fz_buchungen` `f` on(`f`.`PersNr` = `a`.`persnr` and `f`.`Datum` = `a`.`datum`)) left join `tbl_abwesenheitsgrund` `b` on(`a`.`wert` = `b`.`kuerzel`)) where `a`.`datum` between '2023-01-31' and curdate() and `d`.`arbeitstag` = 1 and `a`.`persnr` > 8000 and `b`.`anwesenheit` not in ('Frei','URL') and weekday(`a`.`bekannt_seit`) + (to_days(`a`.`datum`) - to_days(`a`.`bekannt_seit`)) <= 19 and `p`.`taetigkeit` in ('Lagerhelfer','Staplerfahrer') and `f`.`Schicht` <> ''), WEEK0 as (select `a`.`wochentag` - 7 AS `wochentag`,`a`.`schicht` AS `schicht`,count(case when cast(`a`.`bekannt_seit` as time) + interval weekday(`a`.`bekannt_seit`) day < cast(`fd`.`fd` as time) + interval weekday(`fd`.`fd`) + 7 day then 1 end) AS `früher`,count(case when cast(`a`.`bekannt_seit` as time) + interval weekday(`a`.`bekannt_seit`) day >= cast(`fd`.`fd` as time) + interval weekday(`fd`.`fd`) + 7 day then 1 end) AS `später` from (`dataset` `a` join `filedate` `fd`) group by `a`.`wochentag`,`a`.`schicht`), WEEK1 as (select `a`.`wochentag` AS `wochentag`,`a`.`schicht` AS `schicht`,count(case when cast(`a`.`bekannt_seit` as time) + interval weekday(`a`.`bekannt_seit`) day < cast(`fd`.`fd` as time) + interval weekday(`fd`.`fd`) day then 1 end) AS `früher`,count(case when cast(`a`.`bekannt_seit` as time) + interval weekday(`a`.`bekannt_seit`) day >= cast(`fd`.`fd` as time) + interval weekday(`fd`.`fd`) day then 1 end) AS `später` from (`dataset` `a` join `filedate` `fd`) group by `a`.`wochentag`,`a`.`schicht`), WEEK2 as (select `a`.`wochentag` + 7 AS `wochentag`,`a`.`schicht` AS `schicht`,count(case when cast(`a`.`bekannt_seit` as time) + interval weekday(`a`.`bekannt_seit`) day < cast(`fd`.`fd` as time) + interval weekday(`fd`.`fd`) - 7 day then 1 end) AS `früher`,count(case when cast(`a`.`bekannt_seit` as time) + interval weekday(`a`.`bekannt_seit`) day >= cast(`fd`.`fd` as time) + interval weekday(`fd`.`fd`) - 7 day then 1 end) AS `später` from (`dataset` `a` join `filedate` `fd`) where `a`.`wochentag` <= 4 group by `a`.`wochentag`,`a`.`schicht`), 2weeks as (select `a`.`wochentag` AS `wochentag`,`a`.`schicht` AS `schicht`,`a`.`früher` + coalesce(`b`.`früher`,0) + coalesce(`c`.`früher`,0) AS `früher`,`a`.`später` + coalesce(`b`.`später`,0) + coalesce(`c`.`später`,0) AS `später` from ((`week1` `a` left join `week2` `b` on(`a`.`wochentag` = `b`.`wochentag` and `a`.`schicht` = `b`.`schicht`)) left join `week0` `c` on(`a`.`wochentag` = `c`.`wochentag` and `a`.`schicht` = `c`.`schicht`)) order by `a`.`wochentag`,`a`.`schicht`)select cast(`filedate`.`fd` as date) + interval `2weeks`.`wochentag` - weekday(cast(`filedate`.`fd` as date)) day AS `datum`,`2weeks`.`schicht` AS `schicht`,`2weeks`.`später` / (`2weeks`.`früher` + `2weeks`.`später`) AS `decay` from (`2weeks` join `filedate`);
